"""Recording protocol only: does not certify Qt paint, geometry, or a host."""
import pytest
from synapse.panel.designsystem import qss


@pytest.mark.parametrize('name', ['gate_fidelity', 'ctx_memory', 'chat_connection'])
def test_repaired_state_helper_repolishes_on_every_transition(name):
    class Target:
        def __init__(self):
            self.events = []
        def setProperty(self, key, value):
            self.events.append(('property', key, value))
        def style(self):
            return self
        def unpolish(self, target):
            assert target is self
            self.events.append(('unpolish',))
        def polish(self, target):
            assert target is self
            self.events.append(('polish',))
        def update(self):
            self.events.append(('update',))

    target = Target()
    for value in ('first', 'second', 'first'):
        target.events.clear()
        qss.sweep_a_style(target, name, value)
        assert target.events == [('property', 'sweep_a_style', name),
                                 ('property', 'sweep_a_color', value),
                                 ('unpolish',), ('polish',), ('update',)]
